// Cotizador → CRM de G54 (12-oct). Lo llama la app del cotizador una vez por cotización guardada.
// Crea o actualiza el trato (upsert de G54 por teléfono o, sin teléfono, por correo) con origen "web",
// la etiqueta origen:<marca> (qr-cajon, qr-tarjeta, P<idea>…) y una nota con el detalle.
const BASE = 'https://apigrowth.mdarthurdigital.com';
const AGENT = 'Bearer REDACTED_G54_AGENT_TOKEN';
const b = $('🔔 Webhook Cotizador').first().json.body || {};

const limpio = (v, max = 200) => String(v ?? '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, max);
const companyId = Number(b.company_id);
const correo = limpio(b.correo || b.email, 150).toLowerCase();
let telDig = String(b.telefono || '').replace(/\D/g, '');
// 10 dígitos sin código de país = número de EE. UU./Canadá (el cotizador atiende Miami): se agrega el 1.
if (telDig.length === 10 && !String(b.telefono || '').trim().startsWith('+')) telDig = '1' + telDig;
const telefono = telDig.length >= 8 && telDig.length <= 15 ? '+' + telDig : '';
const origen = limpio(b.origen || 'web', 40).toLowerCase().replace(/[^a-z0-9_-]/g, '') || 'web';
const precio = Number(b.precio_estimado);
const dryRun = b.dry_run === true || b.dry_run === 'true';

const errores = [];
if (!Number.isInteger(companyId) || companyId <= 0) errores.push('company_id inválido');
if (correo && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(correo)) errores.push('correo inválido');
if (!correo && !telefono) errores.push('falta correo o teléfono');
if (errores.length) return [{ json: { ok: false, motivo: errores.join('; ') } }];

const medidas = [b.largo, b.ancho, b.alto].every(x => x !== undefined && x !== null && x !== '')
  ? `${limpio(b.largo, 10)} x ${limpio(b.ancho, 10)} x ${limpio(b.alto, 10)} pulgadas` : '';
const codigoPost = /^p\d{2,7}$/.test(origen) ? origen.toUpperCase() : '';
const detalle = [
  'Cotización desde el cotizador web' + (b.cotizacion_id ? ' (id ' + limpio(b.cotizacion_id, 40) + ')' : '') + '.',
  'Origen: ' + origen + (codigoPost ? ' (publicación ' + codigoPost + ')' : '') + '.',
  b.tipo_servicio ? 'Servicio: ' + limpio(b.tipo_servicio, 60) + '.' : '',
  medidas ? 'Medidas: ' + medidas + '.' : '',
  b.cantidad ? 'Cantidad: ' + limpio(b.cantidad, 10) + '.' : '',
  Number.isFinite(precio) && precio > 0 ? 'Precio estimado: $' + precio + ' USD.' : '',
  b.fecha ? 'Para: ' + limpio(b.fecha, 40) + '.' : '',
  b.mensaje ? 'Mensaje: ' + limpio(b.mensaje, 500) : '',
].filter(Boolean).join(' ');

const payload = {
  company_id: companyId,
  nombre: limpio(b.nombre, 120) || correo || telefono,
  ...(telefono ? { telefono } : {}),
  ...(correo ? { email: correo } : {}),
  origen: 'web',
  temperatura: 'medio',
  tags: ['origen:' + origen, 'cotizador'],
  ...(Number.isFinite(precio) && precio > 0 ? { valor_estimado: precio } : {}),
  notas: detalle,
};
if (dryRun) return [{ json: { ok: true, dry_run: true, payload } }];

let deal = null;
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/agent/crm/leads',
    headers: { Authorization: AGENT, Accept: 'application/json' }, body: payload, json: true, timeout: 15000 });
  deal = (r && (r.deal || r.data)) || null;
} catch (e) {
  return [{ json: { ok: false, motivo: 'G54 no guardó el trato: ' + String(e.message || e).slice(0, 200) } }];
}
if (!deal || !deal.id) return [{ json: { ok: false, motivo: 'G54 respondió sin trato' } }];
if (Number(deal.company_id) !== companyId) return [{ json: { ok: false, motivo: 'el trato quedó en otra empresa', deal_id: deal.id } }];

let nota = false;
try {
  await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/agent/crm/leads/' + deal.id + '/activities',
    headers: { Authorization: AGENT, Accept: 'application/json' },
    body: { tipo: 'nota', contenido: detalle }, json: true, timeout: 15000 });
  nota = true;
} catch (e) { nota = false; }
return [{ json: { ok: true, deal_id: deal.id, origen, nota } }];

